def transform(grid):
    # Fill the interiors of outlined rectangular frames. The standard fill is 7;
    # the green/3 frame in the examples maps to 2.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=sum(row.count(v) for row in grid))
    for color in set(v for row in grid for v in row):
        if color == bg:
            continue
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not pts:
            continue
        r0,r1 = min(r for r,c in pts), max(r for r,c in pts)
        c0,c1 = min(c for r,c in pts), max(c for r,c in pts)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        # Check a complete rectangular border of this color and an otherwise empty interior.
        if all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1)):
            fill = 2 if color == 3 else 7
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if grid[r][c] == bg:
                        out[r][c] = fill
    return out
