def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc)); stack.append((nr,nc))
            r0, r1 = min(x for x,y in comp), max(x for x,y in comp)
            c0, c1 = min(y for x,y in comp), max(y for x,y in comp)
            # Only rectangular outlines: each border position is this color;
            # all cells within the bounding box belong to the component border.
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = ({(r0,c) for c in range(c0,c1+1)} |
                      {(r1,c) for c in range(c0,c1+1)} |
                      {(r,c0) for r in range(r0,r1+1)} |
                      {(r,c1) for r in range(r0,r1+1)})
            if set(comp) == border:
                fill = 2 if color == 3 else 7
                for rr in range(r0+1,r1):
                    for cc in range(c0+1,c1):
                        if grid[rr][cc] == bg:
                            out[rr][cc] = fill
    return out
